struct TwoSAT {
    int n;
    vector<vector<int>> g, rg;
    vector<int> comp, order;
    vector<bool> vis;
    TwoSAT(int n) : n(n), g(2*n), rg(2*n) {}
    void add_impl(int u, int v) {
        g[u].push_back(v);
        rg[v].push_back(u);
    }
    void add_or(int u, int v) {
        add_impl(u^1, v);
        add_impl(v^1, u);
    }
