        vis[u] = true;
        for (int v : g[u]) if (!vis[v]) dfs1(v);
        order.push_back(u);
    }
    void dfs2(int u, int id) {
        comp[u] = id;
        for (int v : rg[u]) if (comp[v] == -1) dfs2(v, id);
    }
