// 2-SAT implementation
struct TwoSat {
    int n;
    vector<vector<int>> adj, radj;
    vector<int> order, comp;
    vector<bool> vis;

    TwoSat(int n) : n(n), adj(2*n), radj(2*n), comp(2*n), vis(2*n) {}

    // x OR y (x and y are literals: var*2 for true, var*2+1 for false)
    void add_clause(int x, int y) {
        adj[x^1].push_back(y);
        adj[y^1].push_back(x);
        radj[y].push_back(x^1);
        radj[x].push_back(y^1);
    }

    void dfs1(int v) { vis[v]=true; for(int u:adj[v]) if(!vis[u]) dfs1(u); order.push_back(v); }
    void dfs2(int v, int c) { comp[v]=c; for(int u:radj[v]) if(comp[u]==-1) dfs2(u,c); }

    bool solve() {
        fill(vis.begin(),vis.end(),false);
        for(int i=0;i<2*n;i++) if(!vis[i]) dfs1(i);
        fill(comp.begin(),comp.end(),-1);
        int c=0;
        for(int i=2*n-1;i>=0;i--) if(comp[order[i]]==-1) dfs2(order[i],c++);
        for(int i=0;i<n;i++) if(comp[2*i]==comp[2*i+1]) return false;
        return true;
    }
};

