#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<ll> x(N), y(N);
    for (int i = 0; i < N; i++) cin >> x[i] >> y[i];

    auto feasible = [&](ll d) -> bool {
        // dp[a][b]:
        // after processing current interval [L, R],
        // a = whether a flag is placed at L
        // b = whether a flag is placed at R
        // and all chosen positions inside are pairwise at least d apart.
        bool dp[2][2] = {};
        bool ndp[2][2] = {};

        ll L = min(x[0], y[0]);
        ll R = max(x[0], y[0]);

        if (x[0] == y[0]) {
            dp[1][1] = true;
        } else {
            dp[1][0] = true; // choose L
            dp[0][1] = true; // choose R
        }

        for (int i = 1; i < N; i++) {
            ll p = min(x[i], y[i]);
            ll q = max(x[i], y[i]);

            for (int a = 0; a < 2; a++)
                for (int b = 0; b < 2; b++)
                    ndp[a][b] = false;

            for (int a = 0; a < 2; a++) {
                for (int b = 0; b < 2; b++) {
                    if (!dp[a][b]) continue;

                    // Try choosing p
                    if ((!a || p - L >= d) && (!b || R - p >= d)) {
                        ll nL = min(L, p);
                        ll nR = max(R, p);

                        int na = 0, nb = 0;
                        if (nL == L && a) na = 1;
                        if (nL == p) na = 1;
                        if (nR == R && b) nb = 1;
                        if (nR == p) nb = 1;

                        ndp[na][nb] = true;
                    }

                    // Try choosing q
                    if ((!a || q - L >= d) && (!b || R - q >= d)) {
                        ll nL = min(L, q);
                        ll nR = max(R, q);

                        int na = 0, nb = 0;
                        if (nL == L && a) na = 1;
                        if (nL == q) na = 1;
                        if (nR == R && b) nb = 1;
                        if (nR == q) nb = 1;

                        ndp[na][nb] = true;
                    }
                }
            }

            bool any = false;
            for (int a = 0; a < 2; a++) {
                for (int b = 0; b < 2; b++) {
                    dp[a][b] = ndp[a][b];
                    any |= dp[a][b];
                }
            }
            if (!any) return false;

            L = min(L, p);
            R = max(R, q);
        }

        for (int a = 0; a < 2; a++)
            for (int b = 0; b < 2; b++)
                if (dp[a][b]) return true;
        return false;
    };

    ll low = 0, high = (ll)4e18 / 2; // sufficiently large upper bound

    while (high - low > 1) {
        ll mid = low + (high - low) / 2;
        if (feasible(mid)) low = mid;
        else high = mid;
    }

    cout << low << '\n';
    return 0;
}

