#define MAXN 1000
#define MAXV (MAXN * 2)

typedef struct {
    int to, next;
} Edge;

Edge edges[MAXV * MAXV];
int head[MAXV], edge_cnt;

int x[MAXN], y[MAXN];
int n;

int comp[MAXV], comp_cnt;
int order[MAXV], order_cnt;
int visited[MAXV];
int rev_head[MAXV];
Edge rev_edges[MAXV * MAXV];
int rev_edge_cnt;

void add_edge_impl(int u, int v) {
    edges[edge_cnt].to = v;
    edges[edge_cnt].next = head[u];
    head[u] = edge_cnt++;

    rev_edges[rev_edge_cnt].to = u;
    rev_edges[rev_edge_cnt].next = rev_head[v];
    rev_head[v] = rev_edge_cnt++;
}

void dfs1(int u) {
    visited[u] = 1;
    for (int e = head[u]; e != -1; e = edges[e].next) {
        int v = edges[e].to;
        if (!visited[v]) dfs1(v);
    }
    order[order_cnt++] = u;
}

void dfs2(int u, int c) {
    comp[u] = c;
    for (int e = rev_head[u]; e != -1; e = rev_edges[e].next) {
        int v = rev_edges[e].to;
        if (comp[v] == -1) dfs2(v, c);
    }
}

bool check(int d) {
    edge_cnt = 0;
    rev_edge_cnt = 0;
    memset(head, -1, sizeof(head));
    memset(rev_head, -1, sizeof(rev_head));

    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (abs(x[i] - x[j]) < d) {
                add_edge_impl(i * 2, j * 2 + 1);
                add_edge_impl(j * 2, i * 2 + 1);
            }
            if (abs(x[i] - y[j]) < d) {
                add_edge_impl(i * 2, j * 2);
                add_edge_impl(j * 2 + 1, i * 2 + 1);
            }
            if (abs(y[i] - x[j]) < d) {
                add_edge_impl(i * 2 + 1, j * 2 + 1);
                add_edge_impl(j * 2, i * 2);
            }
            if (abs(y[i] - y[j]) < d) {
                add_edge_impl(i * 2 + 1, j * 2);
                add_edge_impl(j * 2 + 1, i * 2);
            }
        }
    }

    memset(visited, 0, sizeof(visited));
    order_cnt = 0;
    for (int i = 0; i < 2 * n; i++) {
        if (!visited[i]) dfs1(i);
    }

    memset(comp, -1, sizeof(comp));
    comp_cnt = 0;
    for (int i = order_cnt - 1; i >= 0; i--) {
        int v = order[i];
        if (comp[v] == -1) dfs2(v, comp_cnt++);
    }

    for (int i = 0; i < n; i++) {
        if (comp[i * 2] == comp[i * 2 + 1]) return false;
    }
    return true;
}

