#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

static inline ll maxll(ll a, ll b) { return a > b ? a : b; }
static inline ll minll(ll a, ll b) { return a < b ? a : b; }

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    ll *x = (ll *)malloc(sizeof(ll) * N);
    ll *y = (ll *)malloc(sizeof(ll) * N);
    for (int i = 0; i < N; i++) {
        scanf("%lld %lld", &x[i], &y[i]);
    }

    /*
      DP check for a fixed d:
      Let dp0 = feasible and the maximum chosen position up to current i
                when flag i is placed at x[i]
          dp1 = same for y[i]
      Transition:
        previous chosen position p must satisfy current_pos - p >= d.
      Since we only need existence, keeping the largest possible previous
      position for each state is sufficient.
    */

    ll low = 0, high = (ll)4e18; // [low, high)
    while (high - low > 1) {
        ll d = low + (high - low) / 2;

        int ok0 = 1, ok1 = 1;
        ll dp0 = x[0], dp1 = y[0];

        for (int i = 1; i < N; i++) {
            int nok0 = 0, nok1 = 0;
            ll ndp0 = 0, ndp1 = 0;

            if (ok0 && x[i] - dp0 >= d) {
                nok0 = 1;
                ndp0 = dp0;
            }
            if (ok1 && x[i] - dp1 >= d) {
                if (!nok0) {
                    nok0 = 1;
                    ndp0 = dp1;
                } else {
                    ndp0 = maxll(ndp0, dp1);
                }
            }
            if (nok0) ndp0 = x[i];

            if (ok0 && y[i] - dp0 >= d) {
                nok1 = 1;
                ndp1 = dp0;
            }
            if (ok1 && y[i] - dp1 >= d) {
                if (!nok1) {
                    nok1 = 1;
                    ndp1 = dp1;
                } else {
                    ndp1 = maxll(ndp1, dp1);
                }
            }
            if (nok1) ndp1 = y[i];

            ok0 = nok0; dp0 = ndp0;
            ok1 = nok1; dp1 = ndp1;
        }

        if (ok0 || ok1) low = d;
        else high = d;
    }

    printf("%lld\n", low);

    free(x);
    free(y);
    return 0;
}

import java.util.*;
import java.io.*;

public class Main {
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;
        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try { st = new StringTokenizer(br.readLine()); }
                catch (IOException e) { e.printStackTrace(); }
            }
            return st.nextToken();
        }
        int nextInt() { return Integer.parseInt(next()); }
    }

    static int N;
    static int[] x, y;
    static List<Integer>[] graph, revGraph;
    static int[] comp;
    static boolean[] visited;
    static List<Integer> order;

    public static void main(String[] args) {
        FastReader in = new FastReader();
        N = in.nextInt();
        x = new int[N];
        y = new int[N];
        int[] coords = new int[2 * N];
        for (int i = 0; i < N; i++) {
            x[i] = in.nextInt();
            y[i] = in.nextInt();
            coords[2 * i] = x[i];
            coords[2 * i + 1] = y[i];
        }
        Arrays.sort(coords);

        int lo = 0, hi = coords[2 * N - 1] - coords[0] + 1;
        while (hi - lo > 1) {
            int mid = (lo + hi) / 2;
            if (possible(mid)) lo = mid;
            else hi = mid;
        }
        System.out.println(lo);
    }

    static boolean possible(int d) {
        int V = 2 * N;
        graph = new ArrayList[V];
        revGraph = new ArrayList[V];
        for (int i = 0; i < V; i++) {
            graph[i] = new ArrayList<>();
            revGraph[i] = new ArrayList<>();
        }

        // Add implications: if two positions are too close, they can't both be chosen
        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
                // i's x and j's x
                if (Math.abs(x[i] - x[j]) < d) {
                    addClause(i, true, j, true);
                }
                // i's x and j's y
                if (Math.abs(x[i] - y[j]) < d) {
                    addClause(i, true, j, false);
                }
                // i's y and j's x
                if (Math.abs(y[i] - x[j]) < d) {
                    addClause(i, false, j, true);
                }
                // i's y and j's y
                if (Math.abs(y[i] - y[j]) < d) {
                    addClause(i, false, j, false);
                }
            }
        }

        // Kosaraju
        order = new ArrayList<>();
        visited = new boolean[V];
        for (int i = 0; i < V; i++) if (!visited[i]) dfs1(i);
        comp = new int[V];
        Arrays.fill(comp, -1);
        int id = 0;
        for (int i = V - 1; i >= 0; i--) {
            int v = order.get(i);
            if (comp[v] == -1) dfs2(v, id++);
        }
        for (int i = 0; i < N; i++) {
            if (comp[2 * i] == comp[2 * i + 1]) return false;
        }
        return true;
    }

    static void addClause(int i, boolean vi, int j, boolean vj) {
        // (¬A ∨ ¬B) means A → ¬B and B → ¬A
        // A = (i, vi), B = (j, vj)
        int a = 2 * i + (vi ? 0 : 1);
        int na = a ^ 1;
        int b = 2 * j + (vj ? 0 : 1);
        int nb = b ^ 1;
        graph[a].add(nb);
        revGraph[nb].add(a);
        graph[b].add(na);
        revGraph[na].add(b);
    }

    static void dfs1(int v) {
        visited[v] = true;
        for (int u : graph[v]) if (!visited[u]) dfs1(u);
        order.add(v);
    }

    static void dfs2(int v, int id) {
        comp[v] = id;
        for (int u : revGraph[v]) if (comp[u] == -1) dfs2(u, id);
    }
}

