public class Main {
    static int[] comp;
    static int[] order_arr;
    static List<Integer>[] graph, rgraph;
    static boolean[] visited;
    static int n_nodes;
    static int ptr;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());
        long[] x = new long[N], y = new long[N];
        for (int i = 0; i < N; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            x[i] = Long.parseLong(st.nextToken());
            y[i] = Long.parseLong(st.nextToken());
        }

        long lo = 0, hi = (long)2e9;
        while (lo < hi) {
            long mid = (lo + hi + 1) / 2;
            if (check(N, x, y, mid)) lo = mid;
            else hi = mid - 1;
        }
        System.out.println(lo);
    }

    @SuppressWarnings("unchecked")
    static boolean check(int N, long[] x, long[] y, long d) {
        n_nodes = 2 * N;
        graph = new List[n_nodes];
        rgraph = new List[n_nodes];
        for (int i = 0; i < n_nodes; i++) {
            graph[i] = new ArrayList<>();
            rgraph[i] = new ArrayList<>();
        }

        for (int i = 0; i < N; i++) {
            for (int j = i+1; j < N; j++) {
                long[] pi = {x[i], y[i]};
                long[] pj = {x[j], y[j]};
                for (int a = 0; a < 2; a++) {
                    for (int b = 0; b < 2; b++) {
                        if (Math.abs(pi[a] - pj[b]) < d) {
                            // can't have (i=a) and (j=b)
                            // (i=a) -> (j=1-b)
                            addEdge(2*i+a, 2*j+(1-b));
                            // (j=b) -> (i=1-a)
                            addEdge(2*j+b, 2*i+(1-a));
                        }
                    }
                }
            }
        }

        // Kosaraju's SCC
        visited = new boolean[n_nodes];
        order_arr = new int[n_nodes];
        ptr = 0;
        for (int i = 0; i < n_nodes; i++) if (!visited[i]) dfs1(i);
        comp = new int[n_nodes];
        Arrays.fill(comp, -1);
        int c = 0;
        for (int i = n_nodes-1; i >= 0; i--) {
            int v = order_arr[i];
            if (comp[v] == -1) dfs2(v, c++);
        }
        for (int i = 0; i < N; i++) {
            if (comp[2*i] == comp[2*i+1]) return false;
        }
        return true;
    }

    static void dfs1(int v) {
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{v, 0});
        visited[v] = true;
        while (!stack.isEmpty()) {
            int[] cur = stack.peek();
            int u = cur[0];
            if (cur[1] < graph[u].size()) {
                int w = graph[u].get(cur[1]++);
                if (!visited[w]) { visited[w] = true; stack.push(new int[]{w, 0}); }
            } else { stack.pop(); order_arr[ptr++] = u; }
        }
    }

    static void dfs2(int v, int c) {
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(v); comp[v] = c;
        while (!stack.isEmpty()) {
            int u = stack.pop();
            for (int w : rgraph[u]) if (comp[w] == -1) { comp[w] = c; stack.push(w); }
        }
    }

    static void addEdge(int u, int v) {
        graph[u].add(v);
        rgraph[v].add(u);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static int N;
    static long[] x, y;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        N = fs.nextInt();
        x = new long[N];
        y = new long[N];
        long minV = Long.MAX_VALUE, maxV = Long.MIN_VALUE;

        for (int i = 0; i < N; i++) {
            x[i] = fs.nextLong();
            y[i] = fs.nextLong();
            minV = Math.min(minV, Math.min(x[i], y[i]));
            maxV = Math.max(maxV, Math.max(x[i], y[i]));
        }

        long low = 0;
        long high = maxV - minV + 1; // ng

        while (high - low > 1) {
            long mid = (low + high) >>> 1;
            if (can(mid)) low = mid;
            else high = mid;
        }

        System.out.println(low);
    }

    static boolean can(long d) {
        int total = 2 * N;
        long[] pos = new long[total];
        int[] var = new int[total];
        int[] choice = new int[total]; // 0 -> x_i, 1 -> y_i

        for (int i = 0; i < N; i++) {
            pos[2 * i] = x[i];
            var[2 * i] = i;
            choice[2 * i] = 0;

            pos[2 * i + 1] = y[i];
            var[2 * i + 1] = i;
            choice[2 * i + 1] = 1;
        }

        Integer[] ord = new Integer[total];
        for (int i = 0; i < total; i++) ord[i] = i;
        Arrays.sort(ord, Comparator.comparingLong(a -> pos[a]));

        long[] spos = new long[total];
        int[] svar = new int[total];
        int[] schoice = new int[total];
        int[] idxX = new int[N];
        int[] idxY = new int[N];

        for (int i = 0; i < total; i++) {
            int id = ord[i];
            spos[i] = pos[id];
            svar[i] = var[id];
            schoice[i] = choice[id];
            if (choice[id] == 0) idxX[var[id]] = i;
            else idxY[var[id]] = i;
        }

        TwoSAT sat = new TwoSAT(N);

        // For each pair of candidate positions closer than d, they cannot both be chosen.
        // Add clause: not (a and b) => (!a OR !b)
        int r = 0;
        for (int l = 0; l < total; l++) {
            while (r < total && spos[r] - spos[l] < d) r++;
            for (int j = l + 1; j < r; j++) {
                int iVar = svar[l];
                int jVar = svar[j];
                if (iVar == jVar) continue;

                boolean a = (schoice[l] == 1); // variable value that selects this position
                boolean b = (schoice[j] == 1);

                sat.addNand(iVar, a, jVar, b);
            }
        }

        return sat.satisfiable();
    }

    static class TwoSAT {
        int n;
        ArrayList<Integer>[] g, rg;

        @SuppressWarnings("unchecked")
        TwoSAT(int n) {
            this.n = n;
            g = new ArrayList[2 * n];
            rg = new ArrayList[2 * n];
            for (int i = 0; i < 2 * n; i++) {
                g[i] = new ArrayList<>();
                rg[i] = new ArrayList<>();
            }
        }

        int id(int var, boolean val) {
            return 2 * var + (val ? 1 : 0);
        }

        void addImp(int a, int b) {
            g[a].add(b);
            rg[b].add(a);
        }

        // forbid (x=va) and (y=vb) simultaneously
        void addNand(int x, boolean va, int y, boolean vb) {
            int a = id(x, va);
            int na = id(x, !va);
            int b = id(y, vb);
            int nb = id(y, !vb);
            addImp(a, nb);
            addImp(b, na);
        }

        boolean satisfiable() {
            int m = 2 * n;
            boolean[] used = new boolean[m];
            int[] order = new int[m];
            int ordPtr = 0;

            for (int i = 0; i < m; i++) {
                if (!used[i]) {
                    ordPtr = dfs1Iter(i, used, order, ordPtr);
                }
            }

            int[] comp = new int[m];
            Arrays.fill(comp, -1);
            int cid = 0;
            for (int i = m - 1; i >= 0; i--) {
                int v = order[i];
                if (comp[v] == -1) {
                    dfs2Iter(v, cid++, comp);
                }
            }

            for (int i = 0; i < n; i++) {
                if (comp[2 * i] == comp[2 * i + 1]) return false;
            }
            return true;
        }

        int dfs1Iter(int start, boolean[] used, int[] order, int ordPtr) {
            ArrayDeque<int[]> st = new ArrayDeque<>();
            st.push(new int[]{start, 0});
            used[start] = true;

            while (!st.isEmpty()) {
                int[] cur = st.peek();
                int v = cur[0];
                int idx = cur[1];
                if (idx < g[v].size()) {
                    int to = g[v].get(idx);
                    cur[1]++;
                    if (!used[to]) {
                        used[to] = true;
                        st.push(new int[]{to, 0});
                    }
                } else {
                    order[ordPtr++] = v;
                    st.pop();
                }
            }
            return ordPtr;
        }

        void dfs2Iter(int start, int cid, int[] comp) {
            ArrayDeque<Integer> st = new ArrayDeque<>();
            st.push(start);
            comp[start] = cid;
            while (!st.isEmpty()) {
                int v = st.pop();
                for (int to : rg[v]) {
                    if (comp[to] == -1) {
                        comp[to] = cid;
                        st.push(to);
                    }
                }
            }
        }
    }
}

import sys

def main():
    input = sys.stdin.readline
    N = int(input())
    pts = [tuple(map(int, input().split())) for _ in range(N)]

    # Check if it is possible to choose one point from each pair
    # so that every two chosen points differ by at least d.
    def feasible(d: int) -> bool:
        # dp0: possible if we choose x_i for current i
        # dp1: possible if we choose y_i for current i
        dp0 = True
        dp1 = True

        for i in range(N - 1):
            x1, y1 = pts[i]
            x2, y2 = pts[i + 1]

            ndp0 = False
            ndp1 = False

            if dp0:
                if abs(x1 - x2) >= d:
                    ndp0 = True
                if abs(x1 - y2) >= d:
                    ndp1 = True
            if dp1:
                if abs(y1 - x2) >= d:
                    ndp0 = True
                if abs(y1 - y2) >= d:
                    ndp1 = True

            dp0, dp1 = ndp0, ndp1
            if not dp0 and not dp1:
                return False

        return dp0 or dp1

    # Binary search the answer.
    lo, hi = 0, 10**18 + 1  # feasible(lo)=True, feasible(hi)=False
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid

    print(lo)

if __name__ == "__main__":
    main()
